--
-- Estructura para la vista `vista_estadisticas_bloque`
--
DROP TABLE IF EXISTS `vista_estadisticas_bloque`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_estadisticas_bloque`  AS SELECT `b`.`id` AS `id`, `b`.`nombre` AS `nombre`, count(distinct `v`.`congresista_id`) AS `total_congresistas`, count(`v`.`id`) AS `total_votos`, sum(case when `v`.`voto` = 'A FAVOR' then 1 else 0 end) AS `votos_favor`, sum(case when `v`.`voto` = 'EN CONTRA' then 1 else 0 end) AS `votos_contra`, sum(case when `v`.`voto` = 'AUSENTE' then 1 else 0 end) AS `ausencias`, round(sum(case when `v`.`voto` = 'A FAVOR' then 1 else 0 end) * 100.0 / nullif(sum(case when `v`.`voto` in ('A FAVOR','EN CONTRA') then 1 else 0 end),0),2) AS `porcentaje_favor` FROM (`bloques` `b` left join `votos` `v` on(`b`.`id` = `v`.`bloque_id`)) GROUP BY `b`.`id`, `b`.`nombre` ;

