CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_estadisticas_congresista`  AS SELECT `c`.`id` AS `id`, `c`.`nombre` AS `nombre`, count(`v`.`id`) AS `total_votaciones`, sum(case when `v`.`voto` = 'A FAVOR' then 1 else 0 end) AS `votos_favor`, sum(case when `v`.`voto` = 'EN CONTRA' then 1 else 0 end) AS `votos_contra`, sum(case when `v`.`voto` = 'AUSENTE' then 1 else 0 end) AS `ausencias`, sum(case when `v`.`voto` = 'LICENCIA' then 1 else 0 end) AS `licencias`, round(sum(case when `v`.`voto` = 'A FAVOR' then 1 else 0 end) * 100.0 / nullif(sum(case when `v`.`voto` in ('A FAVOR','EN CONTRA') then 1 else 0 end),0),2) AS `porcentaje_favor`, round(sum(case when `v`.`voto` = 'AUSENTE' then 1 else 0 end) * 100.0 / count(`v`.`id`),2) AS `porcentaje_ausencias` FROM (`congresistas` `c` left join `votos` `v` on(`c`.`id` = `v`.`congresista_id`)) GROUP BY `c`.`id`, `c`.`nombre` ;

